import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        File nota = new File("nota");
        nota.mkdirs();
        for (File f : nota.listFiles()) {
            f.delete();
        }
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            new File(nota, in.nextLine()).createNewFile();
        }
        String[] isi = nota.list();
        Arrays.sort(isi);
        for (String n : isi) {
            System.out.println(n);
        }
        System.out.println("Jumlah: " + isi.length);
    }
}
